module matrix_io
   use matrix_kinds, only : dp
   use matrix_status, only : matrix_success, matrix_err_io, matrix_err_invalid
   use matrix_sparse, only : csr_matrix, csr_from_triplet
   implicit none
   private
   public :: write_matrix_market, read_matrix_market
   public :: write_dense_text, read_dense_text

contains

   subroutine write_matrix_market(filename, a, info, symmetric)
      character(len=*), intent(in) :: filename
      type(csr_matrix), intent(in) :: a
      integer, intent(out) :: info
      logical, intent(in), optional :: symmetric
      integer :: unit, ios, i, k, nout
      logical :: sym
      sym = .false.
      if (present(symmetric)) sym = symmetric
      open(newunit=unit, file=filename, status='replace', action='write', iostat=ios)
      if (ios /= 0) then
         info = matrix_err_io
         return
      end if
      if (sym) then
         write(unit, '(a)') '%%MatrixMarket matrix coordinate real symmetric'
         nout = 0
         do i = 1, a%nrow
            do k = a%row_ptr(i), a%row_ptr(i + 1) - 1
               if (i >= a%col_ind(k)) nout = nout + 1
            end do
         end do
      else
         write(unit, '(a)') '%%MatrixMarket matrix coordinate real general'
         nout = a%nnz()
      end if
      write(unit, '(a)') '% Generated by matrix-fortran'
      write(unit, '(i0,1x,i0,1x,i0)') a%nrow, a%ncol, nout
      do i = 1, a%nrow
         do k = a%row_ptr(i), a%row_ptr(i + 1) - 1
            if (.not. sym .or. i >= a%col_ind(k)) then
               write(unit, '(i0,1x,i0,1x,es24.16e3)') i, a%col_ind(k), a%values(k)
            end if
         end do
      end do
      close(unit)
      info = matrix_success
   end subroutine write_matrix_market

   subroutine read_matrix_market(filename, a, info)
      character(len=*), intent(in) :: filename
      type(csr_matrix), intent(out) :: a
      integer, intent(out) :: info
      integer :: unit, ios, nrow, ncol, nnz, i, nall
      integer, allocatable :: rows(:), cols(:)
      real(dp), allocatable :: vals(:)
      character(len=512) :: line
      logical :: symmetric, pattern
      open(newunit=unit, file=filename, status='old', action='read', iostat=ios)
      if (ios /= 0) then
         info = matrix_err_io
         return
      end if
      read(unit, '(a)', iostat=ios) line
      if (ios /= 0 .or. index(adjustl(line), '%%MatrixMarket matrix coordinate') /= 1) then
         close(unit)
         info = matrix_err_invalid
         return
      end if
      symmetric = index(lowercase(line), 'symmetric') > 0
      pattern = index(lowercase(line), 'pattern') > 0
      do
         read(unit, '(a)', iostat=ios) line
         if (ios /= 0) then
            close(unit)
            info = matrix_err_io
            return
         end if
         if (len_trim(line) > 0 .and. line(1:1) /= '%') exit
      end do
      read(line, *, iostat=ios) nrow, ncol, nnz
      if (ios /= 0 .or. nrow < 0 .or. ncol < 0 .or. nnz < 0) then
         close(unit)
         info = matrix_err_invalid
         return
      end if
      nall = merge(2 * nnz, nnz, symmetric)
      allocate(rows(nall), cols(nall), vals(nall))
      nall = 0
      do i = 1, nnz
         if (pattern) then
            read(unit, *, iostat=ios) rows(nall + 1), cols(nall + 1)
            vals(nall + 1) = 1.0_dp
         else
            read(unit, *, iostat=ios) rows(nall + 1), cols(nall + 1), vals(nall + 1)
         end if
         if (ios /= 0) then
            close(unit)
            info = matrix_err_io
            return
         end if
         nall = nall + 1
         if (symmetric .and. rows(nall) /= cols(nall)) then
            rows(nall + 1) = cols(nall)
            cols(nall + 1) = rows(nall)
            vals(nall + 1) = vals(nall)
            nall = nall + 1
         end if
      end do
      close(unit)
      call csr_from_triplet(nrow, ncol, rows(:nall), cols(:nall), vals(:nall), a, info)
   end subroutine read_matrix_market

   pure function lowercase(text) result(out)
      character(len=*), intent(in) :: text
      character(len=len(text)) :: out
      integer :: i, code
      do i = 1, len(text)
         code = iachar(text(i:i))
         if (code >= iachar('A') .and. code <= iachar('Z')) then
            out(i:i) = achar(code + iachar('a') - iachar('A'))
         else
            out(i:i) = text(i:i)
         end if
      end do
   end function lowercase

   subroutine write_dense_text(filename, a, info)
      character(len=*), intent(in) :: filename
      real(dp), intent(in) :: a(:,:)
      integer, intent(out) :: info
      integer :: unit, ios, i
      open(newunit=unit, file=filename, status='replace', action='write', iostat=ios)
      if (ios /= 0) then
         info = matrix_err_io
         return
      end if
      write(unit, '(i0,1x,i0)') size(a, 1), size(a, 2)
      do i = 1, size(a, 1)
         write(unit, '(*(es24.16e3,1x))') a(i, :)
      end do
      close(unit)
      info = matrix_success
   end subroutine write_dense_text

   subroutine read_dense_text(filename, a, info)
      character(len=*), intent(in) :: filename
      real(dp), allocatable, intent(out) :: a(:,:)
      integer, intent(out) :: info
      integer :: unit, ios, nrow, ncol, i
      open(newunit=unit, file=filename, status='old', action='read', iostat=ios)
      if (ios /= 0) then
         allocate(a(0, 0))
         info = matrix_err_io
         return
      end if
      read(unit, *, iostat=ios) nrow, ncol
      if (ios /= 0 .or. nrow < 0 .or. ncol < 0) then
         close(unit)
         allocate(a(0, 0))
         info = matrix_err_invalid
         return
      end if
      allocate(a(nrow, ncol))
      do i = 1, nrow
         read(unit, *, iostat=ios) a(i, :)
         if (ios /= 0) then
            close(unit)
            info = matrix_err_io
            return
         end if
      end do
      close(unit)
      info = matrix_success
   end subroutine read_dense_text

end module matrix_io
